import{_ as i,D as o,o as t,c as r,j as l,a,I as d,w as h,am as n}from"./chunks/framework.DXw8qDd0.js";const q=JSON.parse('{"title":"Codex使用技巧与工作流","description":"","frontmatter":{"title":"Codex使用技巧与工作流","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex使用技巧与工作流.md","filePath":"笔记/Codex/Codex使用技巧与工作流.md"}'),s={name:"笔记/Codex/Codex使用技巧与工作流.md"},c=n('<h1 id="codex-使用技巧与工作流" tabindex="-1">Codex 使用技巧与工作流 <a class="header-anchor" href="#codex-使用技巧与工作流" aria-label="Permalink to &quot;Codex 使用技巧与工作流&quot;">​</a></h1><p>本文档总结提升 Codex 使用效率的实用技巧和常用工作流。</p><hr><h2 id="基础技巧" tabindex="-1">基础技巧 <a class="header-anchor" href="#基础技巧" aria-label="Permalink to &quot;基础技巧&quot;">​</a></h2><ul><li>明确目标：在 Prompt 中写清楚输入、输出和约束。</li><li>提供上下文：给出文件路径、现有结构、错误日志，减少猜测。</li><li>拆分任务：把大任务切成若干小步骤，逐步推进。</li><li>保持一致：统一命名、风格、注释方式，避免混用。</li></ul><hr><h2 id="prompt-设计" tabindex="-1">Prompt 设计 <a class="header-anchor" href="#prompt-设计" aria-label="Permalink to &quot;Prompt 设计&quot;">​</a></h2><h3 id="结构化-prompt-示例" tabindex="-1">结构化 Prompt 示例 <a class="header-anchor" href="#结构化-prompt-示例" aria-label="Permalink to &quot;结构化 Prompt 示例&quot;">​</a></h3><ol><li>背景：项目使用什么技术栈和架构。</li><li>任务：希望 Codex 完成什么目标。</li><li>输入：提供哪些文件、日志或数据。</li><li>输出：期望返回什么格式，例如代码、步骤、报告。</li><li>约束：禁止改动哪些文件、遵循哪些规范。</li></ol><h3 id="提升质量的技巧" tabindex="-1">提升质量的技巧 <a class="header-anchor" href="#提升质量的技巧" aria-label="Permalink to &quot;提升质量的技巧&quot;">​</a></h3><ul><li>要求 Codex 先给方案再写代码。</li><li>明确测试要求：正常路径 + 边界条件 + 异常路径。</li><li>用示例说明期望输出格式。</li><li>指定可接受改动范围，避免波及无关文件。</li></ul><hr><h2 id="常用工作流" tabindex="-1">常用工作流 <a class="header-anchor" href="#常用工作流" aria-label="Permalink to &quot;常用工作流&quot;">​</a></h2><h3 id="_1-需求到实现" tabindex="-1">1. 需求到实现 <a class="header-anchor" href="#_1-需求到实现" aria-label="Permalink to &quot;1. 需求到实现&quot;">​</a></h3><ul><li>先整理需求要点。</li><li>让 Codex 列出实现步骤。</li><li>逐步生成代码并验证。</li><li>完成后要求 Codex 给出回归建议。</li></ul><h3 id="_2-调试流" tabindex="-1">2. 调试流 <a class="header-anchor" href="#_2-调试流" aria-label="Permalink to &quot;2. 调试流&quot;">​</a></h3><ul><li>提供错误信息和复现步骤。</li><li>请 Codex 给出可能原因列表。</li><li>让 Codex 给出排查命令与修复方案。</li><li>修复后补充测试防止复发。</li></ul><h3 id="_3-重构流" tabindex="-1">3. 重构流 <a class="header-anchor" href="#_3-重构流" aria-label="Permalink to &quot;3. 重构流&quot;">​</a></h3><ul><li>说明重构目标和限制。</li><li>让 Codex 给出重构计划。</li><li>增量修改，每步都运行验证。</li><li>最后让 Codex 检查命名、结构、注释。</li></ul><h3 id="_4-测试流" tabindex="-1">4. 测试流 <a class="header-anchor" href="#_4-测试流" aria-label="Permalink to &quot;4. 测试流&quot;">​</a></h3><ul><li>提供函数签名、业务规则和边界条件。</li><li>让 Codex 生成测试用例。</li><li>人工补充关键场景。</li><li>用测试结果反馈优化实现。</li></ul><hr><h2 id="协作习惯" tabindex="-1">协作习惯 <a class="header-anchor" href="#协作习惯" aria-label="Permalink to &quot;协作习惯&quot;">​</a></h2><ul><li>每次对话保持单一主题。</li><li>长任务使用检查点，阶段性确认结果。</li><li>对重要改动做 diff 审查。</li><li>把有效 Prompt 记录下来形成模板。</li></ul><hr><h2 id="效率提升建议" tabindex="-1">效率提升建议 <a class="header-anchor" href="#效率提升建议" aria-label="Permalink to &quot;效率提升建议&quot;">​</a></h2><ul><li>先写接口规范，再让 Codex 填充实现。</li><li>优先修复结构问题，再优化细节。</li><li>用简短明确的指令，避免模糊描述。</li><li>生成后自己再做一轮精修。</li></ul><hr>',28);function u(_,x,m,p,b,C){const e=o("VPNolebaseInlineLinkPreview");return t(),r("div",null,[c,l("blockquote",null,[l("p",null,[a("📎 "),d(e,{href:"/ocdsync/笔记/"},{default:h(()=>[a("📒 返回笔记索引")]),_:1})])])])}const f=i(s,[["render",u]]);export{q as __pageData,f as default};
